async def act(page):
    """
    1) Apply Status = 'Canceled' filter on the current Orders grid.
    2) Paginate through the filtered results, collecting cancelled orders grouped by customer name.
    3) Identify the customer with the most cancellations.
    4) Open that customer's most recent cancelled order(s) and extract SKUs from the order items table.

    Return value: the function returns a comma-separated string of unique SKUs (most-recent cancelled order(s) for the top customer)
    and also stores the result on page._magento_extracted_skus for callers that inspect the page object.
    """
    import re
    from datetime import datetime
    import asyncio

    # Defensive small wait for UI to settle
    try:
        await page.wait_for_timeout(300)
    except Exception:
        pass

    # KB helpers review: none of the provided knowledge-base helpers directly query the orders grid
    # and compute per-customer cancellation counts or extract SKUs from order detail pages. So we do not call them.

    # Try to close any obvious modal/overlay buttons that might block interactions (best-effort)
    try:
        # try several common accessible names for close buttons
        for name in ("Close", "close", "×", "X", "Dismiss"):
            btn = page.get_by_role("button", name=name)
            if await btn.count() > 0:
                try:
                    await btn.nth(0).click()
                    await page.wait_for_timeout(200)
                except Exception:
                    # ignore and continue trying other names
                    pass
    except Exception:
        pass

    # 1) Locate the Status filter combobox that contains a 'Canceled' or 'Cancelled' option
    status_cb = None
    status_label = None
    try:
        comboboxes = page.get_by_role("combobox")
        cb_count = await comboboxes.count()
        for i in range(cb_count):
            cb = comboboxes.nth(i)
            # read option visible texts
            try:
                option_texts = await cb.evaluate("el => Array.from(el.options).map(o => o.innerText || o.text)")
            except Exception:
                option_texts = []
            if not option_texts:
                continue
            for opt_text in option_texts:
                if not opt_text:
                    continue
                if ("Canceled" in opt_text) or ("Cancelled" in opt_text):
                    status_cb = cb
                    status_label = opt_text
                    break
            if status_cb:
                break
    except Exception:
        status_cb = None
        status_label = None

    # If we found the combobox, select the matching option
    if status_cb is not None and status_label is not None:
        try:
            await status_cb.select_option(label=status_label)
            await page.wait_for_timeout(300)
        except Exception:
            # fallback: try to select by value if label selection fails
            try:
                opts = await status_cb.evaluate("el => Array.from(el.options).map(o => ({v: o.value, t: o.innerText||o.text}))")
                found_value = None
                for o in opts:
                    t = o.get('t') or ''
                    if 'Canceled' in t or 'Cancelled' in t:
                        found_value = o.get('v')
                        break
                if found_value is not None:
                    await status_cb.select_option(value=found_value)
                    await page.wait_for_timeout(300)
            except Exception:
                pass

    # Click the Search button to apply the filter; prefer the scoped cell first
    try:
        cell = page.get_by_role('cell', name='Reset Filter Search')
        if await cell.count() > 0:
            search_btn = cell.get_by_role('button', name='Search')
            if await search_btn.count() > 0:
                try:
                    await search_btn.nth(0).click()
                    # grid may refresh via XHR; wait a bit for it
                    try:
                        await page.wait_for_load_state('networkidle')
                    except Exception:
                        await page.wait_for_timeout(700)
                    await page.wait_for_timeout(300)
                except Exception:
                    pass
        else:
            # fallback to page-level Search button
            top_search = page.get_by_role('button', name='Search')
            if await top_search.count() > 0:
                try:
                    await top_search.nth(0).click()
                    try:
                        await page.wait_for_load_state('networkidle')
                    except Exception:
                        await page.wait_for_timeout(700)
                    await page.wait_for_timeout(300)
                except Exception:
                    pass
    except Exception:
        # final fallback: try clicking any button with 'Search' in name
        try:
            alt_search = page.get_by_role('button').filter(has_text='Search')
            if await alt_search.count() > 0:
                await alt_search.nth(0).click()
                await page.wait_for_timeout(500)
        except Exception:
            pass

    # 2) Paginate and collect cancelled orders by customer
    customers = {}  # name -> list of {order, date, href}
    max_pages = 1000
    pages_visited = 0

    while pages_visited < max_pages:
        pages_visited += 1
        # small pause for grid to settle
        await page.wait_for_timeout(300)

        try:
            rows = page.get_by_role('row')
            rcount = await rows.count()
        except Exception:
            rcount = 0

        for ri in range(rcount):
            try:
                row = rows.nth(ri)
            except Exception:
                continue

            # Only data rows contain a 'View' link. Check for presence first.
            try:
                view_links = row.get_by_role('link', name='View')
                if await view_links.count() == 0:
                    continue
            except Exception:
                continue

            # Extract cells safely
            try:
                cells = row.get_by_role('cell')
                ccount = await cells.count()
            except Exception:
                ccount = 0

            if ccount < 5:
                # not a full data row
                continue

            # Extract fields with narrow try/except
            try:
                order_number = (await cells.nth(1).inner_text()).strip()
            except Exception:
                order_number = ''
            try:
                purchased_on = (await cells.nth(3).inner_text()).strip()
            except Exception:
                purchased_on = ''
            try:
                bill_to = (await cells.nth(4).inner_text()).strip()
            except Exception:
                bill_to = ''

            href = None
            try:
                if await view_links.count() > 0:
                    href = await view_links.nth(0).get_attribute('href')
            except Exception:
                href = None

            name = bill_to or 'UNKNOWN'
            customers.setdefault(name, []).append({'order': order_number, 'date': purchased_on, 'href': href})

        # Attempt to go to next page; if no link, break
        try:
            next_link = page.get_by_role('link', name='Go to Next page')
            if await next_link.count() == 0:
                break
            # click next and wait for navigation or a short timeout for JS refresh
            try:
                async with page.expect_navigation(timeout=3000):
                    await next_link.nth(0).click()
                # allow grid to stabilize
                await page.wait_for_timeout(400)
            except Exception:
                # maybe it's a JS refresh without navigation
                try:
                    await next_link.nth(0).click()
                except Exception:
                    break
                await page.wait_for_timeout(700)
            # continue to next page loop
            continue
        except Exception:
            break

    # If no cancelled orders found, return empty string
    if not customers:
        try:
            page._magento_extracted_skus = ''
        except Exception:
            pass
        return ''

    # 3) Identify the customer with the most cancellations
    try:
        top_customer = max(customers.items(), key=lambda kv: len(kv[1]))[0]
    except Exception:
        # fallback to the first customer
        top_customer = next(iter(customers.keys()))

    top_orders = customers.get(top_customer, [])

    # 4) Determine most recent cancelled order(s) for that customer
    def parse_date(s):
        if not s:
            return None
        s = s.replace('\u00A0', ' ').strip()
        fmts = [
            '%B %d, %Y %I:%M:%S %p',  # e.g. May 30, 2023 11:55:09 PM
            '%b %d, %Y %I:%M:%S %p',
            '%B %d, %Y %I:%M %p',
            '%b %d, %Y %I:%M %p',
            '%Y-%m-%d %H:%M:%S',
            '%m/%d/%Y %I:%M:%S %p',
        ]
        for f in fmts:
            try:
                return datetime.strptime(s, f)
            except Exception:
                continue
        # try to extract plausible substring
        m = re.search(r"(\w+ \d{1,2}, \d{4} .*|\d{4}-\d{2}-\d{2} .*|\d{1,2}/\d{1,2}/\d{4} .*)", s)
        if m:
            for f in fmts:
                try:
                    return datetime.strptime(m.group(1), f)
                except Exception:
                    continue
        return None

    max_dt = None
    for o in top_orders:
        parsed = parse_date(o.get('date', ''))
        o['dt'] = parsed
        if parsed and (max_dt is None or parsed > max_dt):
            max_dt = parsed

    if max_dt is not None:
        most_recent_orders = [o for o in top_orders if o.get('dt') == max_dt]
    else:
        # if no parseable dates, use the latest lexicographic date string
        best = max((o.get('date', '') for o in top_orders), default='')
        most_recent_orders = [o for o in top_orders if o.get('date', '') == best]

    # 5) For each most-recent order, open in a new page and extract SKUs
    skus = []
    seen = set()

    origin_base = None
    try:
        # build a base origin for relative hrefs: take scheme+host from current page URL
        # e.g. http://dockerized-magento.local
        from urllib.parse import urlparse
        p = urlparse(page.url)
        origin_base = f"{p.scheme}://{p.netloc}"
    except Exception:
        origin_base = ''

    for o in most_recent_orders:
        href = o.get('href')
        if not href:
            continue
        # normalize href to absolute URL if it starts with '/'
        if href.startswith('/') and origin_base:
            full_href = origin_base + href
        else:
            full_href = href

        new_page = None
        try:
            new_page = await page.context.new_page()
            await new_page.goto(full_href)
            try:
                await new_page.wait_for_load_state('networkidle')
            except Exception:
                await new_page.wait_for_timeout(700)
            await new_page.wait_for_timeout(300)
        except Exception:
            if new_page:
                try:
                    await new_page.close()
                except Exception:
                    pass
            continue

        # best-effort: close any modal on the order view that might block
        try:
            for name in ("Close", "close", "×", "X", "Dismiss"):
                btn = new_page.get_by_role("button", name=name)
                if await btn.count() > 0:
                    try:
                        await btn.nth(0).click()
                        await new_page.wait_for_timeout(200)
                    except Exception:
                        pass
        except Exception:
            pass

        sku_table = None
        try:
            tables = new_page.get_by_role('table')
            tcount = await tables.count()
            for ti in range(tcount):
                t = tables.nth(ti)
                try:
                    ttext = await t.inner_text()
                except Exception:
                    ttext = ''
                if 'SKU' in ttext or 'Sku' in ttext or 'sku' in ttext:
                    sku_table = t
                    break
        except Exception:
            sku_table = None

        if not sku_table:
            try:
                await new_page.close()
            except Exception:
                pass
            continue

        try:
            trows = sku_table.get_by_role('row')
            trcount = await trows.count()
            if trcount == 0:
                await new_page.close()
                continue
        except Exception:
            try:
                await new_page.close()
            except Exception:
                pass
            continue

        # identify SKU header index
        sku_idx = None
        try:
            header_cells = trows.nth(0).get_by_role('cell')
            hcount = await header_cells.count()
            for hi in range(hcount):
                try:
                    htext = (await header_cells.nth(hi).inner_text()).strip()
                except Exception:
                    htext = ''
                if htext and (htext.strip().lower() == 'sku' or 'sku' in htext or 'Sku' in htext):
                    sku_idx = hi
                    break
        except Exception:
            sku_idx = None

        # extract SKUs from data rows
        for ri in range(1, trcount):
            try:
                row_cells = trows.nth(ri).get_by_role('cell')
                cell_count = await row_cells.count()
            except Exception:
                cell_count = 0
            sku_text = ''
            if sku_idx is not None and sku_idx < cell_count:
                try:
                    sku_text = (await row_cells.nth(sku_idx).inner_text()).strip()
                except Exception:
                    sku_text = ''
            else:
                # fallback: scan row text for token-like SKU
                try:
                    row_text = await trows.nth(ri).inner_text()
                except Exception:
                    row_text = ''
                tokens = re.split(r"\s+", row_text)
                for tok in tokens:
                    if tok and re.match(r'^[\w\-\./]+$', tok):
                        # heuristically pick first token that looks like an SKU
                        sku_text = tok
                        break

            if sku_text:
                sku_text = sku_text.strip()
                if sku_text and sku_text not in seen:
                    seen.add(sku_text)
                    skus.append(sku_text)

        try:
            await new_page.close()
        except Exception:
            pass

    result = ','.join(skus)
    try:
        page._magento_extracted_skus = result
    except Exception:
        pass
    return result

